const listSettlements = `-- name: ListSettlements :many
SELECT s.id, s.reference, s.batch_id, s.version_no, s.provider_organization_id,
       s.payer_organization_id, s.currency_code,
       trim_scale(s.approved_amount)::text AS approved_amount,
       trim_scale(s.withheld_amount)::text AS withheld_amount,
       trim_scale(s.payable_amount)::text AS payable_amount,
       trim_scale(s.paid_amount)::text AS paid_amount,
       s.due_date, s.settlement_method, s.status, s.approved_by, s.approved_at, s.checked_by,
       s.posting_id, s.cancel_reason_code, s.created_at, s.row_version,
       o.display_name AS provider_name,
       b.reference AS batch_reference,
       b.decided_by AS batch_decided_by
  FROM billing.settlement s
  JOIN billing.batch b ON b.tenant_id = s.tenant_id AND b.id = s.batch_id
  JOIN directory.tenant_organization t
    ON t.tenant_id = s.tenant_id AND t.id = s.provider_organization_id
  JOIN directory.organization o ON o.id = t.organization_id
 WHERE s.tenant_id = $1
   AND (cardinality($2::uuid[]) = 0
        OR s.provider_organization_id = ANY($2::uuid[]))
   AND ($3::uuid IS NULL
        OR s.provider_organization_id = $3::uuid)
   AND ($4::uuid IS NULL
        OR s.payer_organization_id = $4::uuid)
   AND ($5::uuid IS NULL OR s.batch_id = $5::uuid)
   AND ($6::text IS NULL OR s.status = $6::text)
   AND ($7::text IS NULL
        OR s.currency_code = $7::text)
   AND ($8::date IS NULL OR s.due_date >= $8::date)
   AND ($9::date IS NULL OR s.due_date <= $9::date)
   AND ($10::timestamptz IS NULL
        OR (s.created_at, s.id) < ($10::timestamptz,
                                   $11::uuid))
 ORDER BY s.created_at DESC, s.id DESC
 LIMIT $12
`

type ListSettlementsParams struct {
	TenantID               uuid.UUID
	ScopeIds               []uuid.UUID
	ProviderOrganizationID uuid.NullUUID
	PayerOrganizationID    uuid.NullUUID
	BatchID                uuid.NullUUID
	Status                 *string
	CurrencyCode           *string
	DueFrom                pgtype.Date
	DueTo                  pgtype.Date
	AfterCreatedAt         *time.Time
	AfterID                uuid.NullUUID
	PageSize               int32
}

type ListSettlementsRow struct {
	ID                     uuid.UUID
	Reference              string
	BatchID                uuid.UUID
	VersionNo              int32
	ProviderOrganizationID uuid.UUID
	PayerOrganizationID    uuid.NullUUID
	CurrencyCode           string
	ApprovedAmount         string
	WithheldAmount         string
	PayableAmount          string
	PaidAmount             string
	DueDate                pgtype.Date
	SettlementMethod       string
	Status                 string
	ApprovedBy             uuid.NullUUID
	ApprovedAt             *time.Time
	CheckedBy              uuid.NullUUID
	PostingID              uuid.NullUUID
	CancelReasonCode       *string
	CreatedAt              time.Time
	RowVersion             int64
	ProviderName           string
	BatchReference         string
	BatchDecidedBy         uuid.NullUUID
}

// One page of the keyset on (created_at DESC, id DESC).
func (q *Queries) ListSettlements(ctx context.Context, arg ListSettlementsParams) ([]ListSettlementsRow, error) {
	rows, err := q.db.Query(ctx, listSettlements,
		arg.TenantID,
		arg.ScopeIds,
		arg.ProviderOrganizationID,
		arg.PayerOrganizationID,
		arg.BatchID,
		arg.Status,
		arg.CurrencyCode,
		arg.DueFrom,
		arg.DueTo,
		arg.AfterCreatedAt,
		arg.AfterID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSettlementsRow
	for rows.Next() {
		var i ListSettlementsRow
		if err := rows.Scan(
			&i.ID,
			&i.Reference,
			&i.BatchID,
			&i.VersionNo,
			&i.ProviderOrganizationID,
			&i.PayerOrganizationID,
			&i.CurrencyCode,
			&i.ApprovedAmount,
			&i.WithheldAmount,
			&i.PayableAmount,
			&i.PaidAmount,
			&i.DueDate,
			&i.SettlementMethod,
			&i.Status,
			&i.ApprovedBy,
			&i.ApprovedAt,
			&i.CheckedBy,
			&i.PostingID,
			&i.CancelReasonCode,
			&i.CreatedAt,
			&i.RowVersion,
			&i.ProviderName,
			&i.BatchReference,
			&i.BatchDecidedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

