const lockSettlement = `-- name: LockSettlement :one
SELECT s.id, s.reference, s.batch_id, s.version_no, s.provider_organization_id,
       s.payer_organization_id, s.currency_code,
       trim_scale(s.approved_amount)::text AS approved_amount,
       trim_scale(s.withheld_amount)::text AS withheld_amount,
       trim_scale(s.payable_amount)::text AS payable_amount,
       trim_scale(s.paid_amount)::text AS paid_amount,
       s.due_date, s.settlement_method, s.status, s.approved_by, s.approved_at, s.checked_by,
       s.posting_id, s.cancel_reason_code, s.created_at, s.row_version
  FROM billing.settlement s
 WHERE s.tenant_id = $1
   AND s.id = $2
   AND (cardinality($3::uuid[]) = 0
        OR s.provider_organization_id = ANY($3::uuid[]))
   FOR UPDATE
`

type LockSettlementParams struct {
	TenantID uuid.UUID
	ID       uuid.UUID
	ScopeIds []uuid.UUID
}

type LockSettlementRow struct {
	ID                     uuid.UUID
	Reference              string
	BatchID                uuid.UUID
	VersionNo              int32
	ProviderOrganizationID uuid.UUID
	PayerOrganizationID    uuid.NullUUID
	CurrencyCode           string
	ApprovedAmount         string
	WithheldAmount         string
	PayableAmount          string
	PaidAmount             string
	DueDate                pgtype.Date
	SettlementMethod       string
	Status                 string
	ApprovedBy             uuid.NullUUID
	ApprovedAt             *time.Time
	CheckedBy              uuid.NullUUID
	PostingID              uuid.NullUUID
	CancelReasonCode       *string
	CreatedAt              time.Time
	RowVersion             int64
}

// The same read, holding the row for the length of the command. The approval, the
// cancellation and every payment record take it first: two payment records entered at the
// same moment serialise here, which is what makes the deferred ceiling below a guarantee
// rather than a race.
func (q *Queries) LockSettlement(ctx context.Context, arg LockSettlementParams) (LockSettlementRow, error) {
	row := q.db.QueryRow(ctx, lockSettlement, arg.TenantID, arg.ID, arg.ScopeIds)
	var i LockSettlementRow
	err := row.Scan(
		&i.ID,
		&i.Reference,
		&i.BatchID,
		&i.VersionNo,
		&i.ProviderOrganizationID,
		&i.PayerOrganizationID,
		&i.CurrencyCode,
		&i.ApprovedAmount,
		&i.WithheldAmount,
		&i.PayableAmount,
		&i.PaidAmount,
		&i.DueDate,
		&i.SettlementMethod,
		&i.Status,
		&i.ApprovedBy,
		&i.ApprovedAt,
		&i.CheckedBy,
		&i.PostingID,
		&i.CancelReasonCode,
		&i.CreatedAt,
		&i.RowVersion,
	)
	return i, err
}

const nextSettlementVersion = `-- name: NextSettlementVersion :one
SELECT COALESCE(max(s.version_no), 0)::int + 1 AS next_version
  FROM billing.settlement s
 WHERE s.tenant_id = $1 AND s.batch_id = $2
`

type NextSettlementVersionParams struct {
	TenantID uuid.UUID
	BatchID  uuid.UUID
}

// Which attempt the next settlement on this batch is. It counts cancelled ones too: version
// numbers are the history of the batch's settlements and reusing one would make "settlement 2
// of this batch" a phrase with two meanings.
func (q *Queries) NextSettlementVersion(ctx context.Context, arg NextSettlementVersionParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextSettlementVersion, arg.TenantID, arg.BatchID)
	var next_version int32
	err := row.Scan(&next_version)
	return next_version, err
}

const setReimbursementPaid = `-- name: SetReimbursementPaid :execrows
UPDATE billing.reimbursement
   SET status = 'PAID',
       payment_reference = $1,
       paid_at = $2,
       updated_by = $3
 WHERE tenant_id = $4
   AND id = $5
   AND status IN ('APPROVED', 'PARTIALLY_APPROVED', 'PAYMENT_ORDERED')
`

type SetReimbursementPaidParams struct {
	PaymentReference *string
	PaidAt           *time.Time
	ActorID          uuid.NullUUID
	TenantID         uuid.UUID
	ID               uuid.UUID
}

// Finance entered the reference the bank gave them. It is the end of the road: nothing moves
// a PAID reimbursement afterwards.
func (q *Queries) SetReimbursementPaid(ctx context.Context, arg SetReimbursementPaidParams) (int64, error) {
	result, err := q.db.Exec(ctx, setReimbursementPaid,
		arg.PaymentReference,
		arg.PaidAt,
		arg.ActorID,
		arg.TenantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

