const sumLivePaymentRecords = `-- name: SumLivePaymentRecords :one
SELECT COALESCE(trim_scale(sum(p.amount))::text, '0')::text AS live_total
  FROM billing.payment_record p
 WHERE p.tenant_id = $1
   AND p.settlement_id = $2
   AND p.status <> 'DISPUTED'
`

type SumLivePaymentRecordsParams struct {
	TenantID     uuid.UUID
	SettlementID uuid.UUID
}

// What the settlement's records add up to, disputed ones excluded. The service uses it to
// write `paid_amount`; the deferred trigger computes the same sum and refuses the write when
// the two disagree.
func (q *Queries) SumLivePaymentRecords(ctx context.Context, arg SumLivePaymentRecordsParams) (string, error) {
	row := q.db.QueryRow(ctx, sumLivePaymentRecords, arg.TenantID, arg.SettlementID)
	var live_total string
	err := row.Scan(&live_total)
	return live_total, err
}
